'use server';

import { updateTag } from 'next/cache';

/**
 * Server Action to create a new post.
 * 
 * Uses `updateTag` rather than `revalidateTag` to guarantee read-your-own-writes
 * semantics. This ensures that the cache is immediately expired and the very next 
 * request will block and wait for fresh data, preventing the user from seeing any 
 * stale cached content.
 */
export async function createPost(formData: FormData) {
  // 1. Extract data from the form
  const title = formData.get('title')?.toString();
  const content = formData.get('content')?.toString();

  // 2. Perform the database operation to create the post
  // Example: await db.post.create({ data: { title, content } });

  // 3. Invalidate the 'posts' cache tag
  updateTag('posts');
}

